window.addEventListener("load",function(){const e=document.querySelectorAll(".swiper-slide").length;new Swiper(".p-XX__slider",{slidesPerGroup:1,slidesPerView:3,spaceBetween:45,centeredSlides:!1,slideVisibleClass:"swiper-slide-visible",speed:500,simulateTouch:!0,loop:e>3,autoplay:{delay:5e3,disableOnInteraction:!1},navigation:{prevEl:".c-buttonPrev",nextEl:".c-buttonNext"},breakpoints:{1080:{slidesPerView:3,spaceBetween:30},810:{slidesPerView:2,spaceBetween:20},650:{slidesPerView:2,spaceBetween:20},320:{slidesPerView:1,spaceBetween:0}}})});